module sequence_detector #(
    parameter IDLE = 5'b00001,
    parameter S1   = 5'b00010,
    parameter S2   = 5'b00100,
    parameter S3   = 5'b01000,
    parameter S4   = 5'b10000
) (
    input  clk,
    input  rst_n,
    input  data_in,
    output sequence_detected
);

reg [4:0] current_state;
reg [4:0] next_state;
reg seq_detected;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        current_state <= IDLE;
        seq_detected <= 1'b0;
    end else begin
        current_state <= next_state;
        seq_detected <= 1'b0;
        if (current_state == S4)
            seq_detected <= 1'b1;
    end
end

always @(*) begin
    case (current_state)
        IDLE: begin
            if (data_in) next_state = S1; else next_state = IDLE;
        end
        S1: begin
            if (data_in) next_state = S2; else next_state = IDLE;
        end
        S2: begin
            if (data_in) next_state = S3; else next_state = IDLE;
        end
        S3: begin
            if (data_in) next_state = S4; else next_state = IDLE;
        end
        S4: begin
            next_state = IDLE;
        end
        default: begin
            next_state = IDLE;
        end
    endcase
end

assign sequence_detected = seq_detected;

endmodule
